          "correctAnswer": 1,
          "explanation": "<b>V-てからでないと〜ない：</b>Nếu chưa làm xong việc A thì tuyệt đối không thể làm việc B.<br><b>Dịch nghĩa:</b> Sử dụng thư viện là tự do, nhưng khi mượn tài liệu về thì nếu chưa đăng ký tài khoản thì không thể mượn sách được.<br><i>Phân tích các phương án:</i><br>• <b>1. してからでないと: [Đúng] 登録をしてからでないと本を借りることはできません (nếu chưa đăng ký thì không thể mượn)</b><br>• 2. してはじめて: Kể từ sau khi làm... mới bắt đầu<br>• 3. したからといって: Dù nói là đã làm thì cũng không hẳn<br>• 4. したことによって: Nhờ vào việc đã làm"
